update.foreach:
UPDATE
CBCI_${test.SHOP_NAME}_STOCK
SET
CUBICI_CODE =
CASE WHEN CUBICI_CODE IS NULL THEN #{test.madeCode}
ELSE CUBICI_CODE
END
WHERE LEFT(INPUT_DATE, 10) = #{test.INPUT_DATE}

AND CONCAT(PRODUCT_NO,OPTION1,OPTION2) = #{test.UNIQUE_OPTION}


AND CONCAT(PRODUCT_NO,OPTION1,OPTION2,OPTION3) = #{test.UNIQUE_OPTION}


AND CONCAT(ITEM_NO,OPTION1,OPTION2,OPTION3) = #{test.UNIQUE_OPTION}


AND CONCAT(PRODUCT_NO,MIX_DTL_OPT_NM) = #{test.UNIQUE_OPTION}


AND ${test.prdNo} = #{test.UNIQUE_OPTION}


AND CONCAT(PRODUCT_NO,OPTION_NM_1,OPTION_NM_2,OPTION_NM_3) = #{test.UNIQUE_OPTION}

UPDATE
CBCI_${test.SHOP_NAME}_GOODS
SET
CUBICI_CODE =
CASE WHEN CUBICI_CODE IS NULL THEN #{test.madeCode}
ELSE CUBICI_CODE
END
WHERE LEFT(INPUT_DATE, 10) = #{test.INPUT_DATE}

AND PRODUCT_NO = #{test.UNIQUE_OPTION}


AND PRODUCT_NO = #{test.UNIQUE_OPTION}


AND ITEM_NO = #{test.UNIQUE_OPTION}


AND PRODUCT_NO = #{test.UNIQUE_OPTION}


AND PRODUCT_NO = #{test.UNIQUE_OPTION}

mapper.update:
UPDATE
	CBCI_${SHOP_NAME}
SET

	MATCHING_CODE = ${MATHCING_CODE},
	HEADQUARTER_INVENTORY = ${HEAD_INVEN},
	MATCHING_CANCEL = "Y"


	HEADQUARTER_INVENTORY = ${HEAD_INVEN}


	MATCHING_CODE = #{MATCHING_CODE}

WHERE

	${manageCodeName} = #{MANAGE_CODE}
	AND CUBICI_CODE IS NOT NULL






					SELLER_PRODUCT_ID = #{PRODUCT_NO}


					ITEM_NO = #{PRODUCT_NO}


					PRODUCT_NO = #{PRODUCT_NO}




			CUBICI_CODE = #{CUBICI_CODE}



	AND SHOP_ID = #{SHOP_ID}

mapper.select:
SELECT FOUND_ROWS() AS CNT, FIRST_CAL.* FROM ( SELECT FOUND_ROWS() AS MATCHING_CNT, MATCHING.* FROM( SELECT
SUBMATCHING.SHOP AS MATCHING_TABLE, SUBMATCHING.*
GROUP_CONCAT(SUBMATCHING.SHOP SEPARATOR '^') AS MATCHING_TABLE, SUBMATCHING.*
FROM ( SELECT 1 AS SHOP_TYPE, '인터파크' AS SHOP, 'INTERPARK_GOODS' AS DIVISION, CIG.SHOP_ID, CIG.CUBICI_CODE, CIG.PRODUCT_NO, CIG.MATCHING_CODE, CIG.SELLER_PRODUCT_CODE AS MANAGE_CODE, CIG.PRODUCT_IMG, CIG.PRODUCT_NM AS PRODUCT_NAME, SUBSTRING_INDEX(CIG.CATEGORY, '>', -1) AS CATEGORY, CIG.STOCK_QUANTITY, CIG.SELL_PRICE AS PRICE, CIG.SALES_STATUS AS STATUS, CIG.BRAND_NM AS BRAND, CIG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CIG.HEADQUARTER_INVENTORY AS HEAD_INVEN, CIG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CIG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_INTERPARK_STOCK CIS LEFT JOIN CBCI_INTERPARK_GOODS CIG ON CIS.SHOP_ID = CIG.SHOP_ID AND CIS.PRODUCT_NO = CIG.PRODUCT_NO WHERE CIG.SHOP_ID REGEXP (#{interpark_id}) AND CIG.CUBICI_CODE IS NOT NULL AND CIG.MATCHING_CODE IS NOT NULL UNION ALL SELECT 1 AS SHOP_TYPE, '인터파크' AS SHOP, 'INTERPARK_STOCK' AS DIVISION, CIS.SHOP_ID, CIS.CUBICI_CODE, CIG.PRODUCT_NO, CIS.MATCHING_CODE, CIS.MANAGE_CODE, CIG.PRODUCT_IMG, CONCAT(CIG.PRODUCT_NM, ' / ', CIS.OPTION1, ' ', CIS.OPTION2) AS PRODUCT_NAME, SUBSTRING_INDEX(CIG.CATEGORY, '>', -1) AS CATEGORY, CIS.OPTION_QUANTITY AS STOCK_QUANTITY, CIG.SELL_PRICE + CIS.ADD_PRICE AS PRICE, CIG.SALES_STATUS AS STATUS, CIG.BRAND_NM AS BRAND, CIG.UPD_DATE, CIS.OPTION1 AS OPTION1, CIS.OPTION2 AS OPTION2, '' AS OPTION3, CIS.HEADQUARTER_INVENTORY AS HEAD_INVEN, CIG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CIG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_INTERPARK_STOCK CIS LEFT JOIN CBCI_INTERPARK_GOODS CIG ON CIS.SHOP_ID = CIG.SHOP_ID AND CIS.PRODUCT_NO = CIG.PRODUCT_NO WHERE CIS.SHOP_ID REGEXP (#{interpark_id}) AND CIS.MATCHING_CODE IS NOT NULL UNION ALL SELECT 2 AS SHOP_TYPE, '지마켓' AS SHOP, 'GMARKET_GOODS' AS DIVISION, CGG.SHOP_ID, CGG.CUBICI_CODE, CGG.PRODUCT_NO, CGG.MATCHING_CODE, CGG.SELLER_PRODUCT_CODE AS MANAGE_CODE, CGG.PRODUCT_IMG, CGG.PRODUCT_NM AS PRODUCT_NAME, (CASE WHEN CGG.DETAIL_CATEGORY = '' THEN CGG.SUB_CATEGORY ELSE CGG.DETAIL_CATEGORY END) AS CATEGORY, CGG.STOCK_QUANTITY, CGG.SELL_PRICE AS PRICE, CGG.SALES_STATUS AS STATUS, CGG.BRAND_NM AS BRAND, CGG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CGG.HEADQUARTER_INVENTORY AS HEAD_INVEN, CGG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CGG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_GMARKET_GOODS CGG WHERE CGG.SHOP_ID REGEXP (#{gmarket_id}) AND CGG.CUBICI_CODE IS NOT NULL AND CGG.MATCHING_CODE IS NOT NULL UNION ALL SELECT 2 AS SHOP_TYPE, '지마켓' AS SHOP, 'GMARKET_STOCK' AS DIVISION, CGS.SHOP_ID, CGS.CUBICI_CODE, CGG.PRODUCT_NO, CGS.MATCHING_CODE, CGS.MANAGE_CODE, CGG.PRODUCT_IMG, CONCAT(CGG.PRODUCT_NM, ' / ', CGS.OPTION1, ' ', CGS.OPTION2, ' ', CGS.OPTION3) AS PRODUCT_NAME, (CASE WHEN CGG.DETAIL_CATEGORY = '' THEN CGG.SUB_CATEGORY ELSE CGG.DETAIL_CATEGORY END) AS CATEGORY, CGS.OPTION_STOCK AS STOCK_QUANTITY, CGG.SELL_PRICE + CGS.ADD_PRICE AS PRICE, CGG.SALES_STATUS AS STATUS, CGG.BRAND_NM AS BRAND, CGG.UPD_DATE, CGS.OPTION1 AS OPTION1, CGS.OPTION2 AS OPTION2, CGS.OPTION3 AS OPTION3, CGS.HEADQUARTER_INVENTORY AS HEAD_INVEN, CGG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CGG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_GMARKET_STOCK CGS LEFT JOIN CBCI_GMARKET_GOODS CGG ON CGS.SHOP_ID = CGG.SHOP_ID AND CGS.PRODUCT_NO = CGG.PRODUCT_NO WHERE CGS.SHOP_ID REGEXP (#{gmarket_id}) AND CGS.MATCHING_CODE IS NOT NULL UNION ALL SELECT 3 AS SHOP_TYPE, '옥션' AS SHOP, 'AUCTION_GOODS' AS DIVISION, CAG.SHOP_ID, CAG.CUBICI_CODE, CAG.ITEM_NO, CAG.MATCHING_CODE, CAG.MANAGEMENT_CODE AS MANAGE_CODE, CAG.PRODUCT_IMG AS PRODUCT_IMG, CAG.ITEM_NAME AS PRODUCT_NAME, SUBSTRING_INDEX(CAG.CATEGORY_NAME, '>', -1) AS CATEGORY, CAG.SUM_STOCK_QTY AS STOCK_QUANTITY, CAG.SELLING_PRICE AS PRICE, CAG.SELLING_STATUS_CODE AS STATUS, CAG.BRAND_NAME AS BRAND, CAG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CAG.HEADQUARTER_INVENTORY AS HEAD_INVEN, CAG.SHIPPING_COST AS D_CHARGE, DATE_FORMAT(CAG.ITEM_REGIST_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_AUCTION_GOODS CAG WHERE CAG.SHOP_ID REGEXP (#{auction_id}) AND CAG.CUBICI_CODE IS NOT NULL AND CAG.MATCHING_CODE IS NOT NULL UNION ALL SELECT 3 AS SHOP_TYPE, '옥션' AS SHOP, 'AUCTION_STOCK' AS DIVISION, CAS.SHOP_ID, CAS.CUBICI_CODE, CAG.ITEM_NO, CAS.MATCHING_CODE, CAS.MANAGE_CODE AS MANAGE_CODE, CAG.PRODUCT_IMG AS PRODUCT_IMG, CONCAT(CAG.ITEM_NAME, ' / ', CAS.OPTION1, ' ', CAS.OPTION2, ' ', CAS.OPTION3) AS PRODUCT_NAME, SUBSTRING_INDEX(CAG.CATEGORY_NAME, '>', -1) AS CATEGORY, CAS.OPTION_STOCK AS STOCK_QUANTITY, CAG.SELLING_PRICE + CAS.ADD_PRICE AS PRICE, CAG.SELLING_STATUS_CODE AS STATUS, CAG.BRAND_NAME AS BRAND, CAG.UPD_DATE, CAS.OPTION1 AS OPTION1, CAS.OPTION2 AS OPTION2, CAS.OPTION3 AS OPTION3, CAS.HEADQUARTER_INVENTORY AS HEAD_INVEN, CAG.SHIPPING_COST AS D_CHARGE, DATE_FORMAT(CAG.ITEM_REGIST_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_AUCTION_STOCK CAS LEFT JOIN CBCI_AUCTION_GOODS CAG ON CAS.SHOP_ID = CAG.SHOP_ID AND CAS.ITEM_NO = CAG.ITEM_NO WHERE CAS.SHOP_ID REGEXP (#{auction_id}) AND CAS.MATCHING_CODE IS NOT NULL UNION ALL SELECT 4 AS SHOP_TYPE, '11번가' AS SHOP, '11ST_GOODS' AS DIVISION, CSG.SHOP_ID, CSG.CUBICI_CODE, CSG.PRODUCT_NO, CSG.MATCHING_CODE, CSG.SELLER_PRD_CD AS MANAGE_CODE, CSG.PRODUCT_IMG AS PRODUCT_IMG, CSG.PRD_NM AS PRODUCT_NAME, SUBSTRING_INDEX(CSG.CATEGORY_NAME, '>', -1) AS CATEGORY, CSG.QUANTITY AS STOCK_QUANTITY, CSG.SEL_PRC AS PRICE, CSG.SEL_STAT_NM AS STATUS, CSG.BRAND_NAME AS BRAND, CSG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CSG.HEADQUARTER_INVENTORY AS HEAD_INVEN, '0' AS D_CHARGE, DATE_FORMAT(CSG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_11ST_GOODS CSG WHERE CSG.MATCHING_CODE IS NOT NULL AND CSG.CUBICI_CODE IS NOT NULL AND CSG.SHOP_ID REGEXP (#{eleven_id}) UNION ALL SELECT 4 AS SHOP_TYPE, '11번가' AS SHOP, '11ST_STOCK' AS DIVISION, CSS.SHOP_ID, CSS.CUBICI_CODE, CSG.PRODUCT_NO, CSS.MATCHING_CODE, CSS.SELLER_PRD_CD AS MANAGE_CODE, CSG.PRODUCT_IMG AS PRODUCT_IMG, CONCAT(CSG.PRD_NM, ' / ', CSS.MIX_DTL_OPT_NM) AS PRODUCT_NAME, SUBSTRING_INDEX(CSG.CATEGORY_NAME, '>', -1) AS CATEGORY, CSS.STCK_QTY AS STOCK_QUANTITY, CSG.SEL_PRC AS PRICE, CSG.SEL_STAT_NM AS STATUS, CSG.BRAND_NAME AS BRAND, CSG.UPD_DATE, CSS.MIX_DTL_OPT_NM AS OPTION1, '' AS OPTION2, '' AS OPTION3, CSS.HEADQUARTER_INVENTORY AS HEAD_INVEN, '0' AS D_CHARGE, DATE_FORMAT(CSG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_11ST_STOCK CSS LEFT JOIN CBCI_11ST_GOODS CSG ON CSS.SHOP_ID = CSG.SHOP_ID AND CSS.PRODUCT_NO = CSG.PRODUCT_NO WHERE CSS.MATCHING_CODE IS NOT NULL AND CSS.SHOP_ID REGEXP (#{eleven_id}) UNION ALL SELECT 11 AS SHOP_TYPE, '쿠팡' AS SHOP, 'COUPANG_STOCK' AS DIVISION, CCS.SHOP_ID, CCS.CUBICI_CODE, CCS.SELLER_PRODUCT_ID AS MANAGE_CODE, CCS.MATCHING_CODE, CCS.EXTERNAL_VENDOR_SKU AS MANAGE_CODE, CCS.CDN_PATH_1 AS PRODUCT_IMG, CONCAT(CCG.SELLER_PRODUCT_NM, ' / ', CCS.ITEM_NAME) AS PRODUCT_NAME, (SELECT CATEGORY_NAME FROM CBCI_COUPANG_CATEGORY CCC WHERE CATEGORY_CODE = CCG.CATEGORY_CODE) AS CATEGORY, CCS.OPT_AMOUNT_IN_STOCK AS STOCK_QUANTITY, CCS.SALE_PRICE AS PRICE, CCG.STATUS_NAME AS STATUS, CCG.BRAND, CCS.UPD_DATE, CCS.ITEM_NAME AS OPTION1, '' AS OPTION2, '' AS OPTION3, CCS.HEADQUARTER_INVENTORY AS HEAD_INVEN, CCG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CCG.CREATED_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_COUPANG_STOCK CCS LEFT JOIN CBCI_COUPANG_GOODS CCG ON CCS.SHOP_ID = CCG.SHOP_ID AND CCS.SELLER_PRODUCT_ID = CCG.SELLER_PRODUCT_ID WHERE CCS.SHOP_ID = #{coupang_id} AND CCS.CUBICI_CODE IS NOT NULL AND CCS.MATCHING_CODE IS NOT NULL UNION ALL SELECT 14 AS SHOP_TYPE, '네이버' AS SHOP, 'NAVER_GOODS' AS DIVISION, CNG.SHOP_ID, CNG.CUBICI_CODE, CNG.PRODUCT_NO, CNG.MATCHING_CODE, CNG.SELLER_PRODUCT_CODE AS MANAGE_CODE, CNG.PRODUCT_IMG, CNG.PRODUCT_NM AS PRODUCT_NAME, (CASE WHEN CNG.DETAIL_CATEGORY = '' THEN CNG.SUB_CATEGORY ELSE CNG.DETAIL_CATEGORY END) AS CATEGORY, CNG.STOCK_QUANTITY, CNG.SELL_PRICE AS PRICE, CNG.SALES_STATUS AS STATUS, CNG.BRAND_NM AS BRAND, CNG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CNG.HEADQUARTER_INVENTORY AS HEAD_INVEN, CNG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CNG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_NAVER_GOODS CNG WHERE CNG.SHOP_ID REGEXP (#{naver_id}) AND CNG.CUBICI_CODE IS NOT NULL AND CNG.MATCHING_CODE IS NOT NULL UNION ALL SELECT 14 AS SHOP_TYPE, '네이버' AS SHOP, 'NAVER_STOCK' AS DIVISION, CNS.SHOP_ID, CNS.CUBICI_CODE, CNG.PRODUCT_NO, CNS.MATCHING_CODE, CNS.MANAGE_CODE, CNG.PRODUCT_IMG, CONCAT(CNG.PRODUCT_NM, ' / ', CNS.OPTION_NM_1, CNS.OPTION_NM_2, CNS.OPTION_NM_3) AS PRODUCT_NAME, (CASE WHEN CNG.DETAIL_CATEGORY = '' THEN CNG.SUB_CATEGORY ELSE CNG.DETAIL_CATEGORY END) AS CATEGORY, CNS.OPTION_QUANTITY AS STOCK_QUANTITY, CNG.SELL_PRICE + CNS.OPTION_PRICE AS PRICE, CNG.SALES_STATUS AS STATUS, CNG.BRAND_NM AS BRAND, CNS.UPD_DATE, CNS.OPTION_NM_1 AS OPTION1, CNS.OPTION_NM_2 AS OPTION2, CNS.OPTION_NM_3 AS OPTION3, CNS.HEADQUARTER_INVENTORY AS HEAD_INVEN, CNG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CNG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_NAVER_STOCK CNS LEFT JOIN CBCI_NAVER_GOODS CNG ON CNS.SHOP_ID = CNG.SHOP_ID AND CNS.PRODUCT_NO = CNG.PRODUCT_NO WHERE CNS.SHOP_ID REGEXP (#{naver_id}) AND CNS.MATCHING_CODE IS NOT NULL ) SUBMATCHING
GROUP BY SUBMATCHING.MATCHING_CODE
) MATCHING UNION ALL -- 매칭,논매칭 union SELECT FOUND_ROWS() AS NONMATCHING_CNT, NONMATCHING.SHOP AS MATCHING_TABLE, NONMATCHING.* FROM (
SELECT 1 AS SHOP_TYPE, '인터파크' AS SHOP, 'INTERPARK_GOODS' AS DIVISION, CIG.SHOP_ID, CIG.CUBICI_CODE, CIG.PRODUCT_NO, CIG.MATCHING_CODE, CIG.SELLER_PRODUCT_CODE AS MANAGE_CODE, CIG.PRODUCT_IMG, CIG.PRODUCT_NM AS PRODUCT_NAME, SUBSTRING_INDEX(CIG.CATEGORY, '>', -1) AS CATEGORY, CIG.STOCK_QUANTITY, CIG.SELL_PRICE AS PRICE, CIG.SALES_STATUS AS STATUS, CIG.BRAND_NM AS BRAND, CIG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CIG.HEADQUARTER_INVENTORY AS HEAD_INVEN, CIG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CIG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_INTERPARK_GOODS CIG WHERE CIG.SHOP_ID REGEXP (#{interpark_id}) AND CIG.CUBICI_CODE IS NOT NULL AND CIG.MATCHING_CODE IS NULL UNION ALL SELECT 1 AS SHOP_TYPE, '인터파크' AS SHOP, 'INTERPARK_STOCK' AS DIVISION, CIS.SHOP_ID, CIS.CUBICI_CODE, CIG.PRODUCT_NO, CIS.MATCHING_CODE, CIS.MANAGE_CODE, CIG.PRODUCT_IMG, CONCAT(CIG.PRODUCT_NM, ' / ', CIS.OPTION1, ' ', CIS.OPTION2) AS PRODUCT_NAME, SUBSTRING_INDEX(CIG.CATEGORY, '>', -1) AS CATEGORY, CIS.OPTION_QUANTITY AS STOCK_QUANTITY, CIG.SELL_PRICE + CIS.ADD_PRICE AS PRICE, CIG.SALES_STATUS AS STATUS, CIG.BRAND_NM AS BRAND, CIG.UPD_DATE, CIS.OPTION1 AS OPTION1, CIS.OPTION2 AS OPTION2, '' AS OPTION3, CIS.HEADQUARTER_INVENTORY AS HEAD_INVEN, CIG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CIG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_INTERPARK_STOCK CIS LEFT JOIN CBCI_INTERPARK_GOODS CIG ON CIS.SHOP_ID = CIG.SHOP_ID AND CIS.PRODUCT_NO = CIG.PRODUCT_NO WHERE CIS.SHOP_ID REGEXP (#{interpark_id}) AND CIS.MATCHING_CODE IS NULL UNION ALL SELECT 2 AS SHOP_TYPE, '지마켓' AS SHOP, 'GMARKET_GOODS' AS DIVISION, CGG.SHOP_ID, CGG.CUBICI_CODE, CGG.PRODUCT_NO, CGG.MATCHING_CODE, CGG.SELLER_PRODUCT_CODE AS MANAGE_CODE, CGG.PRODUCT_IMG, CGG.PRODUCT_NM AS PRODUCT_NAME, (CASE WHEN CGG.DETAIL_CATEGORY = '' THEN CGG.SUB_CATEGORY ELSE CGG.DETAIL_CATEGORY END) AS CATEGORY, CGG.STOCK_QUANTITY, CGG.SELL_PRICE AS PRICE, CGG.SALES_STATUS AS STATUS, CGG.BRAND_NM AS BRAND, CGG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CGG.HEADQUARTER_INVENTORY AS HEAD_INVEN, CGG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CGG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_GMARKET_GOODS CGG WHERE CGG.SHOP_ID REGEXP (#{gmarket_id}) AND CGG.CUBICI_CODE IS NOT NULL AND CGG.MATCHING_CODE IS NULL UNION ALL SELECT 2 AS SHOP_TYPE, '지마켓' AS SHOP, 'GMARKET_STOCK' AS DIVISION, CGS.SHOP_ID, CGS.CUBICI_CODE, CGG.PRODUCT_NO, CGS.MATCHING_CODE, CGS.MANAGE_CODE, CGG.PRODUCT_IMG, CONCAT(CGG.PRODUCT_NM, ' / ', CGS.OPTION1, ' ', CGS.OPTION2, ' ', CGS.OPTION3) AS PRODUCT_NAME, (CASE WHEN CGG.DETAIL_CATEGORY = '' THEN CGG.SUB_CATEGORY ELSE CGG.DETAIL_CATEGORY END) AS CATEGORY, CGS.OPTION_STOCK AS STOCK_QUANTITY, CGG.SELL_PRICE + CGS.ADD_PRICE AS PRICE, CGG.SALES_STATUS AS STATUS, CGG.BRAND_NM AS BRAND, CGG.UPD_DATE, CGS.OPTION1 AS OPTION1, CGS.OPTION2 AS OPTION2, CGS.OPTION3 AS OPTION3, CGS.HEADQUARTER_INVENTORY AS HEAD_INVEN, CGG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CGG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_GMARKET_STOCK CGS LEFT JOIN CBCI_GMARKET_GOODS CGG ON CGS.SHOP_ID = CGG.SHOP_ID AND CGS.PRODUCT_NO = CGG.PRODUCT_NO WHERE CGS.SHOP_ID REGEXP (#{gmarket_id}) AND CGS.MATCHING_CODE IS NULL UNION ALL SELECT 3 AS SHOP_TYPE, '옥션' AS SHOP, 'AUCTION_GOODS' AS DIVISION, CAG.SHOP_ID, CAG.CUBICI_CODE, CAG.ITEM_NO AS PRODUCT_NO, CAG.MATCHING_CODE, CAG.MANAGEMENT_CODE AS MANAGE_CODE, CAG.PRODUCT_IMG AS PRODUCT_IMG, CAG.ITEM_NAME AS PRODUCT_NAME, SUBSTRING_INDEX(CAG.CATEGORY_NAME, '>', -1) AS CATEGORY, CAG.SUM_STOCK_QTY AS STOCK_QUANTITY, CAG.SELLING_PRICE AS PRICE, CAG.SELLING_STATUS_CODE AS STATUS, CAG.BRAND_NAME AS BRAND, CAG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CAG.HEADQUARTER_INVENTORY AS HEAD_INVEN, CAG.SHIPPING_COST AS D_CHARGE, DATE_FORMAT(CAG.ITEM_REGIST_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_AUCTION_GOODS CAG WHERE CAG.SHOP_ID REGEXP (#{auction_id}) AND CAG.CUBICI_CODE IS NOT NULL AND CAG.MATCHING_CODE IS NULL UNION ALL SELECT 3 AS SHOP_TYPE, '옥션' AS SHOP, 'AUCTION_STOCK' AS DIVISION, CAS.SHOP_ID, CAS.CUBICI_CODE, CAG.ITEM_NO, CAS.MATCHING_CODE, CAS.MANAGE_CODE AS MANAGE_CODE, CAG.PRODUCT_IMG AS PRODUCT_IMG, CONCAT(CAG.ITEM_NAME, ' / ', CAS.OPTION1, ' ', CAS.OPTION2, ' ', CAS.OPTION3) AS PRODUCT_NAME, SUBSTRING_INDEX(CAG.CATEGORY_NAME, '>', -1) AS CATEGORY, CAS.OPTION_STOCK AS STOCK_QUANTITY, CAG.SELLING_PRICE + CAS.ADD_PRICE AS PRICE, CAG.SELLING_STATUS_CODE AS STATUS, CAG.BRAND_NAME AS BRAND, CAG.UPD_DATE, CAS.OPTION1 AS OPTION1, CAS.OPTION2 AS OPTION2, CAS.OPTION3 AS OPTION3, CAS.HEADQUARTER_INVENTORY AS HEAD_INVEN, CAG.SHIPPING_COST AS D_CHARGE, DATE_FORMAT(CAG.ITEM_REGIST_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_AUCTION_STOCK CAS LEFT JOIN CBCI_AUCTION_GOODS CAG ON CAS.SHOP_ID = CAG.SHOP_ID AND CAS.ITEM_NO = CAG.ITEM_NO WHERE CAS.SHOP_ID REGEXP (#{auction_id}) AND CAS.MATCHING_CODE IS NULL UNION ALL SELECT 4 AS SHOP_TYPE, '11번가' AS SHOP, '11ST_GOODS' AS DIVISION, CSG.SHOP_ID, CSG.CUBICI_CODE, CSG.PRODUCT_NO, CSG.MATCHING_CODE, CSG.SELLER_PRD_CD AS MANAGE_CODE, CSG.PRODUCT_IMG AS PRODUCT_IMG, CSG.PRD_NM AS PRODUCT_NAME, SUBSTRING_INDEX(CSG.CATEGORY_NAME, '>', -1) AS CATEGORY, CSG.QUANTITY AS STOCK_QUANTITY, CSG.SEL_PRC AS PRICE, CSG.SEL_STAT_NM AS STATUS, CSG.BRAND_NAME AS BRAND, CSG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CSG.HEADQUARTER_INVENTORY AS HEAD_INVEN, '0' AS D_CHARGE, DATE_FORMAT(CSG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_11ST_GOODS CSG WHERE CSG.SHOP_ID REGEXP (#{eleven_id}) AND CSG.CUBICI_CODE IS NOT NULL AND CSG.MATCHING_CODE IS NULL UNION ALL SELECT 4 AS SHOP_TYPE, '11번가' AS SHOP, '11ST_STOCK' AS DIVISION, CSS.SHOP_ID, CSS.CUBICI_CODE, CSG.PRODUCT_NO, CSS.MATCHING_CODE, CSS.SELLER_PRD_CD AS MANAGE_CODE, CSG.PRODUCT_IMG AS PRODUCT_IMG, CONCAT(CSG.PRD_NM, ' / ', CSS.MIX_DTL_OPT_NM) AS PRODUCT_NAME, SUBSTRING_INDEX(CSG.CATEGORY_NAME, '>', -1) AS CATEGORY, CSS.STCK_QTY AS STOCK_QUANTITY, CSG.SEL_PRC AS PRICE, CSG.SEL_STAT_NM AS STATUS, CSG.BRAND_NAME AS BRAND, CSG.UPD_DATE, CSS.MIX_DTL_OPT_NM AS OPTION1, '' AS OPTION2, '' AS OPTION3, CSS.HEADQUARTER_INVENTORY AS HEAD_INVEN, '0' AS D_CHARGE, DATE_FORMAT(CSG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_11ST_STOCK CSS LEFT JOIN CBCI_11ST_GOODS CSG ON CSS.SHOP_ID = CSG.SHOP_ID AND CSS.PRODUCT_NO = CSG.PRODUCT_NO WHERE CSS.MATCHING_CODE IS NULL AND CSS.SHOP_ID REGEXP (#{eleven_id}) UNION ALL SELECT 11 AS SHOP_TYPE, '쿠팡' AS SHOP, 'COUPANG_STOCK' AS DIVISION, CCS.SHOP_ID, CCS.CUBICI_CODE, CCS.SELLER_PRODUCT_ID AS PRODUCT_NO, CCS.MATCHING_CODE, CCS.EXTERNAL_VENDOR_SKU AS MANAGE_CODE, CCS.CDN_PATH_1 AS PRODUCT_IMG, CONCAT(CCG.SELLER_PRODUCT_NM, ' / ', CCS.ITEM_NAME) AS PRODUCT_NAME, (SELECT CATEGORY_NAME FROM CBCI_COUPANG_CATEGORY CCC WHERE CATEGORY_CODE = CCG.CATEGORY_CODE) AS CATEGORY, CCS.OPT_AMOUNT_IN_STOCK AS STOCK_QUANTITY, CCS.SALE_PRICE AS PRICE, CCG.STATUS_NAME AS STATUS, CCG.BRAND, CCS.UPD_DATE, CCS.ITEM_NAME AS OPTION1, '' AS OPTION2, '' AS OPTION3, CCS.HEADQUARTER_INVENTORY AS HEAD_INVEN, CCG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CCG.CREATED_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_COUPANG_STOCK CCS LEFT JOIN CBCI_COUPANG_GOODS CCG ON CCS.SHOP_ID = CCG.SHOP_ID AND CCS.SELLER_PRODUCT_ID = CCG.SELLER_PRODUCT_ID WHERE CCS.SHOP_ID = #{coupang_id} AND CCS.CUBICI_CODE IS NOT NULL AND CCS.MATCHING_CODE IS NULL UNION ALL SELECT 14 AS SHOP_TYPE, '네이버' AS SHOP, 'NAVER_GOODS' AS DIVISION, CNG.SHOP_ID, CNG.CUBICI_CODE, CNG.PRODUCT_NO, CNG.MATCHING_CODE, CNG.SELLER_PRODUCT_CODE AS MANAGE_CODE, CNG.PRODUCT_IMG, CNG.PRODUCT_NM AS PRODUCT_NAME, (CASE WHEN CNG.DETAIL_CATEGORY = '' THEN CNG.SUB_CATEGORY ELSE CNG.DETAIL_CATEGORY END) AS CATEGORY, CNG.STOCK_QUANTITY, CNG.SELL_PRICE AS PRICE, CNG.SALES_STATUS AS STATUS, CNG.BRAND_NM AS BRAND, CNG.UPD_DATE, '' AS OPTION1, '' AS OPTION2, '' AS OPTION3, CNG.HEADQUARTER_INVENTORY AS HEAD_INVEN, CNG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CNG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_NAVER_GOODS CNG WHERE CNG.SHOP_ID REGEXP (#{naver_id}) AND CNG.CUBICI_CODE IS NOT NULL AND CNG.MATCHING_CODE IS NULL UNION ALL SELECT 14 AS SHOP_TYPE, '네이버' AS SHOP, 'NAVER_STOCK' AS DIVISION, CNS.SHOP_ID, CNS.CUBICI_CODE, CNG.PRODUCT_NO, CNS.MATCHING_CODE, CNS.MANAGE_CODE, CNG.PRODUCT_IMG, CONCAT(CNG.PRODUCT_NM, ' / ', CNS.OPTION_NM_1, CNS.OPTION_NM_2, CNS.OPTION_NM_3) AS PRODUCT_NAME, (CASE WHEN CNG.DETAIL_CATEGORY = '' THEN CNG.SUB_CATEGORY ELSE CNG.DETAIL_CATEGORY END) AS CATEGORY, CNS.OPTION_QUANTITY AS STOCK_QUANTITY, CNG.SELL_PRICE + CNS.OPTION_PRICE AS PRICE, CNG.SALES_STATUS AS STATUS, CNG.BRAND_NM AS BRAND, CNS.UPD_DATE, CNS.OPTION_NM_1 AS OPTION1, CNS.OPTION_NM_2 AS OPTION2, CNS.OPTION_NM_3 AS OPTION3, CNG.HEADQUARTER_INVENTORY AS HEAD_INVEN, CNG.DELIVERY_CHARGE AS D_CHARGE, DATE_FORMAT(CNG.PRODUCT_REG_DATE, '%Y-%m-%d %H:%i:%s') AS REG_DATE FROM CBCI_NAVER_STOCK CNS LEFT JOIN CBCI_NAVER_GOODS CNG ON CNS.SHOP_ID = CNG.SHOP_ID AND CNS.PRODUCT_NO = CNG.PRODUCT_NO WHERE CNS.SHOP_ID REGEXP (#{naver_id}) AND CNS.MATCHING_CODE IS NULL ) NONMATCHING
) FIRST_CAL WHERE FIRST_CAL.MATCHING_CODE = #{MATCHING_CODE} ORDER BY FIRST_CAL.REG_DATE
) FIRST_CAL WHERE FIRST_CAL.MANAGE_CODE = #{MANAGE_CODE}
) FIRST_CAL WHERE FIRST_CAL.PRODUCT_NO= #{PRODUCT_NO}
) FIRST_CAL WHERE FIRST_CAL.CUBICI_CODE = #{CUBICI_CODE}
) FIRST_CAL WHERE FIRST_CAL.PRODUCT_NAME LIKE '%${searchName}%' AND FIRST_CAL.STATUS IN (${sale_status}) AND FIRST_CAL.SHOP_TYPE IN (${SHOP_TYPE_LIST})
ORDER BY ${sortPage} DESC
ORDER BY ${sortPage}
LIMIT ${dataCnt},${dataPerPage}
